--
-- Table structure for table `absensi_guru`
--

DROP TABLE IF EXISTS `absensi_guru`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `absensi_guru` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `guru_id` int(11) unsigned NOT NULL,
  `tanggal` date NOT NULL,
  `status` enum('hadir','terlambat','izin','sakit','alpha','cuti') NOT NULL DEFAULT 'alpha',
  `check_in` time DEFAULT NULL,
  `check_out` time DEFAULT NULL,
  `durasi_menit` int(11) DEFAULT NULL COMMENT 'Duration in minutes between check_in and check_out',
  `foto_check_in` varchar(255) DEFAULT NULL COMMENT 'Selfie photo path for check-in',
  `keterangan_masuk` text DEFAULT NULL COMMENT 'Notes or remarks for check-in',
  `foto_check_out` varchar(255) DEFAULT NULL COMMENT 'Selfie photo path for check-out',
  `keterangan_keluar` text DEFAULT NULL COMMENT 'Notes or remarks for check-out',
  `latitude_check_in` decimal(10,8) DEFAULT NULL COMMENT 'GPS latitude for check-in validation',
  `longitude_check_in` decimal(11,8) DEFAULT NULL COMMENT 'GPS longitude for check-in validation',
  `latitude_check_out` decimal(10,8) DEFAULT NULL COMMENT 'GPS latitude for check-out validation',
  `longitude_check_out` decimal(11,8) DEFAULT NULL COMMENT 'GPS longitude for check-out validation',
  `early_checkout` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Flag if checkout before 8 hours',
  `early_checkout_reason` text DEFAULT NULL COMMENT 'Reason for early checkout if duration < 480 min',
  `catatan` text DEFAULT NULL COMMENT 'Additional notes or remarks',
  `set_by_wakakur` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Flag if status manually set by wakakur',
  `set_by_user_id` int(11) unsigned DEFAULT NULL COMMENT 'User ID who manually set the status (wakakur)',
