--
-- Table structure for table `jurnal_pkl`
--

DROP TABLE IF EXISTS `jurnal_pkl`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `jurnal_pkl` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `siswa_id` int(11) unsigned NOT NULL,
  `nama_kegiatan` varchar(255) NOT NULL,
  `deskripsi` text NOT NULL,
  `foto` varchar(255) DEFAULT NULL,
  `status` enum('pending','disetujui','revisi','ditolak','tinjau_ulang') DEFAULT 'pending',
  `tanggal` date NOT NULL,
  `catatan_pembimbing` text DEFAULT NULL,
  `verified_by` int(11) unsigned DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `jurnal_pkl_verified_by_foreign` (`verified_by`),
  KEY `siswa_id_tanggal` (`siswa_id`,`tanggal`),
  CONSTRAINT `jurnal_pkl_siswa_id_foreign` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `jurnal_pkl_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `jurnal_pkl`
--

LOCK TABLES `jurnal_pkl` WRITE;
/*!40000 ALTER TABLE `jurnal_pkl` DISABLE KEYS */;
/*!40000 ALTER TABLE `jurnal_pkl` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `kategori_pkl_mapping`
--

DROP TABLE IF EXISTS `kategori_pkl_mapping`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `kategori_pkl_mapping` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `tempat_pkl_id` int(11) unsigned NOT NULL,
  `kategori_id` int(11) unsigned NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tempat_pkl_id_kategori_id` (`tempat_pkl_id`,`kategori_id`),
  KEY `kategori_pkl_mapping_kategori_id_foreign` (`kategori_id`),
  KEY `tempat_pkl_id` (`tempat_pkl_id`),
  CONSTRAINT `kategori_pkl_mapping_kategori_id_foreign` FOREIGN KEY (`kategori_id`) REFERENCES `pkl_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
