DROP TABLE IF EXISTS `pkl_progress`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pkl_progress` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_id` int(11) unsigned NOT NULL,
  `tanggal` date NOT NULL,
  `deskripsi` text NOT NULL,
  `langkah_kerja` text DEFAULT NULL,
  `foto` varchar(255) DEFAULT NULL,
  `status` varchar(30) DEFAULT 'draft',
  `catatan_pembimbing` text NOT NULL DEFAULT '',
  `catatan_instruktur` text NOT NULL DEFAULT '',
  `verified_by` int(11) unsigned DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `instruktur_verified_by` int(11) unsigned DEFAULT NULL,
  `instruktur_verified_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pkl_progress_verified_by_foreign` (`verified_by`),
  KEY `task_id_tanggal` (`task_id`,`tanggal`),
  KEY `tanggal` (`tanggal`),
  CONSTRAINT `pkl_progress_task_id_foreign` FOREIGN KEY (`task_id`) REFERENCES `pkl_tasks` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `pkl_progress_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=137 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

