DROP TABLE IF EXISTS `siswa_pkl`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `siswa_pkl` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `siswa_id` int(11) unsigned NOT NULL,
  `tempat_pkl_id` int(11) unsigned NOT NULL,
  `pembimbing_pkl_id` int(11) unsigned DEFAULT NULL,
  `tahun_ajaran` varchar(9) NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `siswa_id_tahun_ajaran` (`siswa_id`,`tahun_ajaran`),
  KEY `siswa_pkl_tempat_pkl_id_foreign` (`tempat_pkl_id`),
  KEY `fk_siswa_pkl_pembimbing` (`pembimbing_pkl_id`),
